const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
// Read SQLite header to confirm it's a valid DB
console.log('File size:', buf.length);
console.log('Header:', buf.slice(0, 16).toString('ascii'));
// Search for strings in the binary
const text = buf.toString('latin1');
const matches = ['ORD-E0E671','cust_003','Sofia','Martinez'];
matches.forEach(m => {
  const idx = text.indexOf(m);
  console.log(m, 'found at offset:', idx);
});
// Find order IDs - look for #W pattern
const regex = /#W\d+/g;
let match;
const orderIds = new Set();
while ((match = regex.exec(text)) !== null) {
  orderIds.add(match[0]);
}
console.log('Order IDs found:', [...orderIds].slice(0, 20));
"

