node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('latin1');

// --- ORDER ORD-E0E671 ---
// Extract a wide context around the order
let idx = text.indexOf('ORD-E0E671');
console.log('============ ORDER ORD-E0E671 RAW CONTEXT ============');
console.log(JSON.stringify(text.slice(Math.max(0,idx-20), idx+300)));

// --- USER user_1d80ab67 (Sofia Ramirez) ---
idx = text.indexOf('user_1d80ab67Sofia');
if (idx === -1) idx = text.indexOf('user_1d80ab67');
console.log('\n============ USER user_1d80ab67 RAW CONTEXT ============');
console.log(JSON.stringify(text.slice(Math.max(0,idx-20), idx+600)));

// --- Payment method cc_21e6eed2 ---
let pmIdx = 0;
let contexts = [];
while (true) {
  pmIdx = text.indexOf('cc_21e6eed2', pmIdx);
  if (pmIdx === -1) break;
  contexts.push(text.slice(Math.max(0,pmIdx-100), pmIdx+150));
  pmIdx++;
}
console.log('\n============ PAYMENT METHOD cc_21e6eed2 OCCURRENCES ============');
contexts.forEach((c,i) => console.log('--- occurrence', i, '---', JSON.stringify(c)));
"

